package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateTimeFormatter_parseInto_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendInstantPattern("yyyy-MM-dd")
                .toFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void testParseInto_StandardDate_ReturnsNewPosition() {
        // Setup a formatter that parses a simple date
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd")
                .toFormatter();

        // Using a MutableDateTime (which implements ReadWritableInstant)
        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0);
        String text = "2023-05-20";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // "yyyy-MM-dd" is 10 characters
        Assert.assertEquals(10, newPos);
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(5, instant.getMonthOfYear());
        Assert.assertEquals(20, instant.getDayOfMonth());
    }

    @Test
    public void testParseInto_WithOffsetParsed_UpdatesChronology() {
        // Setup formatter to parse offset
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd HH:mm:ss Z")
                .withOffsetParsed()
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-05-20 10:00:00 +05:00";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        Assert.assertTrue(newPos > 0);
        // Check if the zone was updated to +05:00
        Assert.assertEquals("+05:00", instant.getZone().getID());
    }

    @Test
    public void testParseInto_WithExplicitZone_PreservesZone() {
        // Setup formatter with a fixed zone
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd")
                .toFormatter()
                .withZone(targetZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(DateTimeZone.UTC);
        String text = "2023-05-20";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(targetZone, instant.getZone());
    }

    @Test
    public void testParseInto_WithPivotYear() {
        // Testing the defaultYear logic via pivot year influence
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yy-MM-dd")
                .withPivotYear(2000)
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "23-05-20"; // Should be 2023

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_WithLocale() {
        // Testing locale influence (though pattern is numeric, we ensure no crash)
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd")
                .toFormatter()
                .withLocale(Locale.FRANCE);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-05-20";

        int newPos = formatter.parseInto(instant, text, 0);

        Assert.assertEquals(10, newPos);
        Assert.assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_PartialText_ReturnsEndPosition() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy")
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-extra";

        int newPos = formatter.parseInto(instant, text, 0);

        // It should only consume "2023" (4 chars)
        Assert.assertEquals(4, newPos);
        Assert.assertEquals(2023, instant.getYear());
    }
}
